import {test,expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
import {pptParityFixture} from '../fixtures/ppt-parity';
// Generated by the production contract/parser/PPTX fixture, not a separate UI layout.
const slide=JSON.parse(readFileSync('src/__tests__/fixtures/ppt-render-contract.json','utf8'));
test('PPT shared contracts render signed charts, crops, code and tables @smoke',async({page},info)=>{
 const fixture=pptParityFixture();const project=fixture.projects.get('9'.repeat(32))!;project.status='completed';
 slide.slideId=project.outline[0].id;slide.id=project.renderTree.slides[0].id;
 Object.assign(project.renderTree.slides[0],slide);
 const errors:string[]=[];page.on('pageerror',error=>errors.push(error.message));page.on('console',message=>{if(message.type()==='error')errors.push(message.text());});
 await page.route('**/api/**',async route=>{const r=await fixture.handle(route.request().method(),new URL(route.request().url()).pathname,route.request().postData()?route.request().postDataJSON():{});if(!r)return route.continue();return route.fulfill({status:r.status,contentType:r.contentType||'application/json',body:typeof r.body==='string'?r.body:JSON.stringify(r.body)});});
 await page.goto('/ppt', {waitUntil:'domcontentloaded'});await page.getByRole('heading',{name:'Workflow fixture',exact:true}).click();
 const editor=page.getByTestId('ppt-structured-editor');
 await expect(editor.getByText('def verify(value):',{exact:true})).toBeVisible();await expect(editor.getByText('return "保留负号"',{exact:false})).toBeVisible();
 await expect(editor.getByRole('cell',{name:'-12.5',exact:true})).toBeVisible();

 const negative=editor.locator('rect[data-value="-4"]');await expect(negative).toHaveCount(1);
 const geometry=await negative.evaluate(element=>({y:Number(element.getAttribute('y')),height:Number(element.getAttribute('height')),zero:Number(element.parentElement!.querySelector('line')!.getAttribute('y1'))}));
 const labelSize=await editor.getByRole('img',{name:'USD: 5, -4, 0',exact:true}).locator('text').first().evaluate(e=>e.getBoundingClientRect().height);expect(labelSize).toBeGreaterThan(8);
 expect(geometry.y).toBeCloseTo(geometry.zero,4);expect(geometry.height).toBeGreaterThan(0);
 const fits=await editor.locator('img').evaluateAll(elements=>elements.map(e=>getComputedStyle(e).objectFit));expect(fits).toEqual(expect.arrayContaining(['contain','cover','fill']));
 const code=editor.getByText('def verify(value):',{exact:true}).locator('..');
 const metrics=await code.evaluate(e=>({height:e.clientHeight,scroll:e.scrollHeight,width:e.clientWidth,scrollWidth:e.scrollWidth,padding:getComputedStyle(e).paddingLeft}));
 expect(metrics.scroll).toBeLessThanOrEqual(metrics.height+1);expect(metrics.scrollWidth).toBeLessThanOrEqual(metrics.width+1);expect(parseFloat(metrics.padding)).toBeGreaterThan(0);
 await page.screenshot({path:info.outputPath('render-contract-desktop.png')});
 await page.setViewportSize({width:980,height:760});await page.screenshot({path:info.outputPath('render-contract-compact.png')});
 // Native 4:3 decks must use their own page ratio and points-per-pixel scale.
 const nativeSlide=project.renderTree.slides[0];nativeSlide.size={width:9144000,height:6858000};
 nativeSlide.elements.forEach(e=>{e.bounds={...e.bounds,x:e.bounds.x*.75,width:e.bounds.width*.75};});
 await page.goto('/ppt', {waitUntil:'domcontentloaded'});await page.getByRole('heading',{name:'Workflow fixture',exact:true}).click();
 const title=page.getByTestId('ppt-structured-editor').getByText('多输入渲染契约 / Cross-input rendering',{exact:true});
 const ratio=await title.evaluate(e=>{const canvas=e.closest('.aspect-video')!;const b=canvas.getBoundingClientRect();return {ratio:b.width/b.height,font:parseFloat(getComputedStyle(e.parentElement!).fontSize),contentWidth:canvas.clientWidth};});
 expect(ratio.ratio).toBeCloseTo(4/3,2);expect(ratio.font/28).toBeCloseTo(ratio.contentWidth/720,2);
 await page.screenshot({path:info.outputPath('render-contract-native-4-3.png')});
 expect(errors).toEqual([]);
});
